#include "stm32g4xx.h"

void tim1_pa8_pwm_init(void) {
    // 1. Enable GPIOA and TIM1 clocks
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    // 2. Configure PA8 as Alternate Function AF6 (TIM1_CH1)
    // Clear mode bits for pin 8 and set to alternate function (10b)
    GPIOA->MODER &= ~(3U << (8 * 2));
    GPIOA->MODER |= (2U << (8 * 2));

    // Set AF6 (0110b) for pin 8 in AFR[1] (AFRH)
    GPIOA->AFR[1] &= ~(0xFU << ((8 - 8) * 4));
    GPIOA->AFR[1] |= (6U << ((8 - 8) * 4));

    // Optional: High speed output
    GPIOA->OSPEEDR |= (3U << (8 * 2));

    // 3. Configure TIM1 for 20 kHz PWM, 25% duty
    // TIM1CLK = 170 MHz. Target = 20 kHz -> 170 MHz / 20 kHz = 8500 cycles.
    // PSC = 0, ARR = 8499.
    // Duty = 25% -> CCR1 = 8500 * 0.25 = 2125.
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    // CCMR1: PWM mode 1 (OC1M = 0110b), enable preload (OC1PE)
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M | TIM_CCMR1_CC1S);
    TIM1->CCMR1 |= (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2);
    TIM1->CCMR1 |= TIM_CCMR1_OC1PE;

    // CCER: Enable CH1 output (CC1E)
    TIM1->CCER |= TIM_CCER_CC1E;

    // BDTR: Main Output Enable (MOE) - crucial for TIM1 / advanced timers
    TIM1->BDTR |= TIM_BDTR_MOE;

    // CR1: Auto-reload preload enable (ARPE) and Counter Enable (CEN)
    TIM1->CR1 |= TIM_CR1_ARPE;
    TIM1->CR1 |= TIM_CR1_CEN;

    // Trigger update event to load registers
    TIM1->EGR |= TIM_EGR_UG;
}

